Gordic.Previews.register("bpl:Doklad", {
    // Ověřování, zda je řádek kompletní
    canRender: function (dto) { return dto.ixp != null; },
    // Samotné vykreslení náhledu
    render: function (div, dto) {
        var s_uhr_txt = "";
        var s_zau_txt = "";
        var sumaUhrazeno;
        var sumaZauctovano;
        if (dto.s_uhr == "0")
            s_uhr_txt = "jres:29750039"; // RC 29750039 : Neuhrazeno
        else if (dto.s_uhr == "10")
            s_uhr_txt = "jres:29750038"; // RC 29750038 : Uhrazeno částečně
        else if (dto.s_uhr == "20")
            s_uhr_txt = "jres:29750040"; // RC 29750040 : Uhrazeno
        if (dto.s_zau == "0")
            s_zau_txt = "jres:29750043"; // RC 29750043 : Nezaúčtováno
        else if (dto.s_zau == "10")
            s_zau_txt = "jres:29750042"; // RC 29750042 : Zaúčtováno částečně
        else if (dto.s_zau == "20")
            s_zau_txt = "jres:29750041"; // RC 29750041 : Zaúčtováno
        sumaUhrazeno = parseDecimal(dto.c_celk_mena).minus(parseDecimal(dto.c_zust_mena)).minus(parseDecimal(dto.c_dor)); // výpočet uhrazené částky
        sumaZauctovano = parseDecimal(dto.c_kzauc).minus(parseDecimal(dto.c_dor)); // výpočet zaúčtované částky
        var currentElement = $(div);
        // data jsou ready -> samotné vytvoření náhledu
        var nazev_esu = (dto.nazev == null) ? dto.esu_txt : dto.nazev; // dto může přijít ze seznamu nebo z detailu
        currentElement.empty().append("<h2 class='g-state-text g-state-active nahled-nadpis'>" + nazev_esu + "</h2><hr style='margin: 0.5rem; opacity: 0.2;'/>");
        Gordic.Previews.displayLinkButton(div, dto);
        $("<div class='gform--view-mode'>").appendTo(currentElement)
            .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
            gformsection("create").gpidbar({ pid: dto.ixp }).
            gformsection("create").
            gformrow("addFieldsRow", "jres:29750108").gformtext(Gordic.Templates.Formatters.date(dto.dat_evid), "bold"). // RC 29750108 : Datum evidence
            gformrow("addFieldsRow", "jres:29750006").gformtext(Gordic.Templates.Formatters.date(dto.dat_spl), "bold"). // RC 29750006 : Datum splatnosti
            gformrow("addFieldsRow", "jres:29750109").gformtext(dto.ac_ag, "bold"). // RC 29750109 : Agendové číslo
            gformrow("addFieldsRow", "jres:29750110").gformtext(dto.ac, "bold"). // RC 29750110 : Evidenční číslo
            gformrow("addFieldsRow", "jres:29750111").gformtext("<b class='g-state-text g-state-info'>" + dto.ktg_typ_txt + "</b>", "bold"). // RC 29750111 : Typ dokladu
            gformrow("addFieldsRow", "jres:29750112").gformtext("<b class='g-state-text g-state-success'>" + (dto.ps_sml != null && dto.ps_sml != "" && dto.ps_sml != undefined ? dto.ps_sml + "<br>" + dto.ps_sml_ac : "----") + "</b>", "bold"). // RC 29750112 : Smlouva/objednávka
            gformsection("create").
            gformrow("addFieldsRow", "jres:29750113").gformtext("<b class='g-state-text g-state-info'>" + s_uhr_txt + "<br>" + s_zau_txt + "</b>", "bold"). // RC 29750113 : Stav dokladu
            gformsection("create").
            gformrow("addFieldsRow", "jres:29750114").gformtext("<b class='g-state-text g-state-error'>" + Gordic.Templates.Formatters.number(dto.c_mena, "C") + " " + dto.mena_zkr, "</b>"). // RC 29750114 : Celková částka v měně
            gformrow("addFieldsRow", "jres:29750115").gformtext("<b class='g-state-text g-state-error'>" + Gordic.Templates.Formatters.number(dto.c_czk || dto.c_celk, "C") + " CZK </b>"). // RC 29750115 : Celková částka v CZK
            gformrow("addFieldsRow", "jres:29750116").gformtext(Gordic.Templates.Formatters.number(dto.c_kuhr, "C") + " CZK"). // RC 29750116 : K úhradě v CZK
            gformrow("addFieldsRow", "jres:29750117").gformtext(Gordic.Templates.Formatters.number(sumaUhrazeno.toNumber(), "C") + " CZK"). // RC 29750117 : Uhrazeno v CZK
            gformrow("addFieldsRow", "jres:29750118").gformtext(Gordic.Templates.Formatters.number(sumaZauctovano.toNumber(), "C") + " CZK"). // RC 29750118 : Zaúčtováno v CZK
            gformsection("create").
            gformrow("addFieldsRow", "jres:29750071").gformtext(dto.popis, "bold"); // RC 29750071 : Popis
        currentElement.resize().find(".gform-section").children("label").first().addClass("g-state-text g-state-error");
    }
});
