                    let b_pom = that.DetailDto.priz_pdp == 0 || that.DetailDto.priz_pdp == 1 && (c_pol.equals(0));
                    b_c_mena = (b_noedit2 == false && b_LIK_nesch && (c_vaz.equals(0) && (that.DetailDto.s_kry ?? 0) < 20 && b_pom || (WebClient.BPLDetailDokladu.jeDokladBezZavazkuNeboDanovy(ktg_typ) /*&& l_navaz == 0*/)));
                    b_ESU = (b_noedit === false && that.DetailDto.s_zau == 0 &&
                        ((that.DetailDto.s_kry ?? 0) < 20 || WebClient.BPLDetailDokladu.jeDokladBezZavazkuNeboDanovy(ktg_typ) && suma_lik_zal_sch.equals(0)) &&
                        ktg_typ != 1382 && ktg_typ != 1383 &&
                        (c_vaz.equals(0) || WebClient.BPLDetailDokladu.jeDokladBezZavazkuNeboDanovy(ktg_typ)) && c_kuhr.equals(0));
