                nactiSeznamVazebDokladu() {
                    var that = this;
                    that.beginOperation("jres:29750207"); // RC 29750207 : Načítání seznamu vazeb dokladů ...
                    return this.call("NactiSeznamVazebDokladu", {}) // volání servrové logiky pro načtení seznamu
                        .then(function (data) {
                        that.dataVazby = data; // uložení dat do proměnné
                        var view = new Gordic.Data.View(data, { key: "ixp" }); // key je důležitý kvůli vyhledávání řádku
                        that.$gridVazby.ggrid("setData", view, true); // TRUE = překreslení gridu
                        that.endOperation(); // konec přesýpacích hodin
                    });
                }
                ;
                //---------------------------------------
