                /**
                 * stejné jako původní actionFlashHandler, avšak má na vstupu params namísto pole akcí. Akce je definována na contentu, sem je pouze předána unitř menuParams
                 * @param opts
                 * @param menuParams parametry pro akce
                 * @param caption nadpis flashe
                 * @returns
                 */
                actionFlashCreateHandlerMenuParams(opts, menuParams, caption) {
                    const flash = opts;
                    flash.create = (ev) => {
                        const root = $(ev.target).find(".gflashpanel__content").empty();
                        root.append(`<p>${caption}</p>`);
                        const $ul = $("<ul>");
                        for (const par of menuParams) {
                            const $li = $("<li>").append($("<a>")).glink({
                                params: par
                            });
                            $li.appendTo($ul);
                        }
                        $ul.appendTo(root);
                    };
                    return flash;
                }
                ;
                /**
                 * Vytvoří flash, který obsahuje odrážky s linkami spustitelných akcí (spíše nepoužívat, lepší nadefinovat akci na content a použít actionFlashCreateHandlerMenuParams)
                 * @param opts
                 * @param actions
                 * @param caption
                 * @returns
                 */
                actionFlashCreateHandler(opts, actions, caption) {
                    const flash = opts;
                    flash.create = (ev) => {
                        const root = $(ev.target).find(".gflashpanel__content").empty();
                        root.append(`<p>${caption}</p>`);
                        const $ul = $("<ul>");
                        for (const act of actions) {
                            const $li = $("<li>").append($("<a>")).glink({
                                params: { action: act }
                            });
                            $li.appendTo($ul);
                        }
                        $ul.appendTo(root);
                    };
                    return flash;
                }
