                GAItestSazbyDPH(zaklad, dan, rekapitulace, korekce) {
                    const that = this;
                    let danTyp = -1; // typ daně
                    if (zaklad.equals(0))
                        return $.when(false); // nelze dělit nulou
                    let sazbaDPH = dan.dividedBy(zaklad).times(100).round(); // výpočet procentuální sazby DPH
                    if (sazbaDPH.equals(21))
                        danTyp = 10; // základní sazba DPH
                    else if (sazbaDPH.equals(12) || sazbaDPH.equals(15))
                        danTyp = 20; // snížená sazba DPH
                    else if (sazbaDPH.equals(10))
                        danTyp = 30; // druhá snížená sazba DPH                
                    if (danTyp !== -1 && rekapitulace) { // má se promítnout i do rekapitulace
                        let Recap = that.recapDPH; // objekt rekapitulace
                        return Recap.setValues([{ dan_typ: danTyp, baseValue: zaklad, tax: dan, sum: zaklad.plus(dan) }], true) // nastavení hodnot do rekapitulace
                            .then(() => {
                            return $.when(that.changeDoruceniPromise, that.changeZdanPlnPromise);
                        })
                            .then(() => {
                            return that.GAInastavPriznakRekapitulace(danTyp, -1, (korekce === true) ? "GAI" : "AI"); // obarvení gridu
                        }).then(() => {
                            return danTyp !== -1; // výsledek
                        });
                    }
                    return $.when(danTyp !== -1); // výsledek
                }
                //----------------------------------------
