                GCalendarGincudsEnum[GCalendarGincudsEnum["NavrhDuleziteUdalosti"] = 10] = "NavrhDuleziteUdalosti";
                GCalendarGincudsEnum[GCalendarGincudsEnum["PrijataUdalost"] = 20] = "PrijataUdalost";
                GCalendarGincudsEnum[GCalendarGincudsEnum["OdmitnutaUdalost"] = 30] = "OdmitnutaUdalost";
