                    //var l_dNovaCastkaMena = this.find(".gfield[data-field=m_oTbCUhraditMena]").gfield('getValue');                        // načtení nové částky
                    //var l_dZbyvaUhraditMena = this.find(".gfield[data-field=m_oTbCZbyvaMena]").gfield('getValue');                        // načtení částky co zbývá uhradit v měně
