                addCastkaLikColumn(gridFormat, dphDto) {
                    return this.addCastkaLikZalohColumn(gridFormat, dphDto.c_z0, dphDto.c_z1, dphDto.c_z2, dphDto.c_z3, dphDto.c_z1_d, dphDto.c_z2_d, dphDto.c_z3_d, dphDto.c_d1, dphDto.c_d2, dphDto.c_d3, dphDto.c_d1_d, dphDto.c_d2_d, dphDto.c_d3_d, dphDto.c_zaokr);
                }
                addCastkaLikZalohColumn(gridFormat, c_z0, c_z1, c_z2, c_z3, c_z1_d, c_z2_d, c_z3_d, c_d1, c_d2, c_d3, c_d1_d, c_d2_d, c_d3_d, c_zaokr) {
                    gridFormat.addCurrencyColumn({
                        name: "c",
                        caption: "jres:29750103", // RC 29750103 : Částka;
                        width: 70,
                        customClass: (ctx) => { return WebClient.GKryLikTools.generateCustomClassFunction(ctx.data.up_stav, this.editable); },
                        editor: (ctx) => {
                            var data = ctx.cellInfo.meta.data;
                            var d = [];
                            if (data.ppk === 0 || data.ppk === 4) {
                                this.pridejCastkuDoNabidky(d, c_z0, "jres:26850035"); //RC 26850035 : Částka bez DPH
                                this.pridejCastkuDoNabidky(d, c_z2, "jres:26850036"); //RC 26850036 : Základní sazba - základ
                                this.pridejCastkuDoNabidky(d, c_z1, "jres:26850037"); //RC 26850037 : Snížená sazba - základ
                                this.pridejCastkuDoNabidky(d, c_z3, "jres:26850038"); //RC 26850038 : Druhá snížená - základ
                                this.pridejCastkuDoNabidky(d, c_z2_d, "jres:26850039"); //RC 26850039 : Základní sazba - základ - dodanění
                                this.pridejCastkuDoNabidky(d, c_z1_d, "jres:26850040"); //RC 26850040 : Snížená sazba - základ - dodanění
                                this.pridejCastkuDoNabidky(d, c_z3_d, "jres:26850041"); //RC 26850041 : Druhá snížená - základ - dodanění
                                //u ppk == 4 nebudu nabízet daň
                                if (data.ppk === 0) {
                                    this.pridejCastkuDoNabidky(d, c_d2_d, "jres:26850042"); //RC 26850042 : Základní sazba - daň - dodanění
                                    this.pridejCastkuDoNabidky(d, c_d1_d, "jres:26850043"); //RC 26850043 : Snížená sazba - daň - dodanění
                                    this.pridejCastkuDoNabidky(d, c_d3_d, "jres:26850044"); //RC 26850044 : Druhá snížená - daň - dodanění
                                }
                                //TO DO: TSK GLikBaseTabNew ř.197
                            }
                            else if (data.ppk === 1 || data.ppk === 5) {
                                this.pridejCastkuDoNabidky(d, c_d2, "jres:26850045"); //RC 26850045 : Základní sazba - daň
                                this.pridejCastkuDoNabidky(d, c_d1, "jres:26850046"); //RC 26850046 : Snížená sazba - daň
                                this.pridejCastkuDoNabidky(d, c_d3, "jres:26850047"); //RC 26850047 : Druhá snížená - daň
                                this.pridejCastkuDoNabidky(d, c_d2_d, "jres:26850042"); //RC 26850042 : Základní sazba - daň - dodanění
                                this.pridejCastkuDoNabidky(d, c_d1_d, "jres:26850043"); //RC 26850043 : Snížená sazba - daň - dodanění
                                this.pridejCastkuDoNabidky(d, c_d3_d, "jres:26850044"); //RC 26850044 : Druhá snížená - daň - dodanění
                                //TO DO: TSK GLikBaseTabNew ř.256
                            }
                            else {
                                this.pridejCastkuDoNabidky(d, c_zaokr, "jres:26850048"); //RC 26850048 : Zaokrouhlení
                            }
                            return {
                                widget: "gselectbox",
                                options: [{
                                        selector: function (opts) {
                                            return new Gordic.Data.Selectors.DefaultSelector($.extend({
                                                data: d,
                                                gridOpts: { searchColumns: ["c", "name"] },
                                                gridFormat: new Gordic.Data.GridFormat()
                                                    .addTextColumn({ name: "name", caption: "Popis" }) //RC 30250024 : Název
                                                    .addCurrencyColumn({ name: "c", caption: "Částka" })
                                                //uid: "cfu_" + options.cfu.name + "#"
                                            }, opts)).show({ /* searchText: $(this).gfield("getValue") */});
                                        },
                                        name: "c",
                                        model: "model.c=value.c",
                                        strict: false,
                                        itemTemplate: "{c:number(C2)}",
                                        invalidTransform: (val) => {
                                            try {
                                                if (typeof val === "string") {
                                                    val = val.replace((Gordic?.Consts).Locale?.decimalSeparator, ".").replace(",", ".").replace(/\s*/g, "");
                                                }
                                                const dec = parseDecimal(val);
                                                if (dec?.isNaN())
                                                    return null;
                                                else
                                                    return { c: dec };
                                            }
                                            catch {
                                                return null;
                                            }
                                        }
                                        //validators: [new Validators.Base({                                                      // validátor
                                        //    stopping: true, message: "Zadaná částka je vyšší než částka dokladu. Zbývá rozepsat " + parseDecimal(that.batoh.c_celk_mena!).minus(that.PristupAkciKontace.sumaRozpisu!).toString() + " " + that.batoh.mena_zkr, validate: (value) => {
                                        //        var novaSuma = sumaRozpisu.add(value);                                          // přičtení částky k již rozepsaným řádkům
                                        //        return novaSuma.lessThanOrEqualTo(that.batoh.c_celk_mena!);                     // porovnání akturální sumy s částkou dokladu
                                        //    }
                                        //})]
                                    }]
                            };
                        }
                    });
                    return gridFormat;
                }
