                            // 25.4.2014 - Michal Prošek - oprava znaménka při ukládání likvidace záloh
                            if (typKontace == 25 /* Gordic.Bpl.Interface.TypKontace.LikvidaceZalohy */ && (that.GlobalniPromenne.agenda === "kdf" || that.GlobalniPromenne.agenda === "kof"))
                                saveInParams.radek.znam = -1;
