                //nepužívá se - nebarví se schválené řádky na modro
                function VolejSchvaleni(vstupy, that, radkyKrylik, detailKontace, dataSentence) {
                    that.beginOperation("jres:26850024"); //RC 26850024 : Probíhá schválení
                    return that.call("Schvaleni", { vstupy: vstupy })
                        .then(() => {
                    }, (err) => {
                        if (err instanceof GServerError) { // Pokud je chyba vyjimka, osetrim si ji tu    
                            const ctx = err.details;
                            if (ctx["exceptionType"] != "Gordic.General.GDataInvalidException") {
                                that.endOperation(); // smaz informacni hlasku
                                return that.dialogs.error(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                            }
                            else {
                                ctx.handled = true; // Nastav si priznak, ze chyba byla osetrena
                                const data = ctx.data;
                                switch (data.exceptionType) {
                                    case "error":
                                        that.endOperation(); // smaz informacni hlasku
                                        return that.dialogs.warning(ctx.baseMessage).createDialogPromise(); // Zobraz dialog a ukonci cinnost
                                    case "question":
                                        return that.dialogs.confirm(ctx.baseMessage, 600, 400).createDialogPromise("yes").then(function () {
                                            switch (data.member) {
                                                case "confirmDph1":
                                                    vstupy.confirmDph1 = true;
                                                    break;
                                                case "confirmDph2":
                                                    vstupy.confirmDph2 = true;
                                                    break;
                                                case "confirmDph3":
                                                    vstupy.confirmDph3 = true;
                                                    break;
                                                case "confirmSchvaleniBezKontroly":
                                                    vstupy.confirmSchvaleniBezKontroly = true;
                                                    break;
                                            }
                                            return VolejSchvaleni(vstupy, that, radkyKrylik, detailKontace, dataSentence); // Volam rekurzivne schvaleni se zmenenymi vstupy
                                        });
                                    case "vyber":
                                        //return this.call("GetSubradaDuzUcet").then((data) => {
                                        return new Gordic.Data.Selectors.DefaultSelector({
                                            related: that.element,
                                            title: "Výběr",
                                            canSelectEmpty: false,
                                            data: data.data,
                                            gridFormat: new Gordic.Data.GridFormat()
                                                .addNumberColumn({
                                                name: "subrada",
                                                caption: "Subřada",
                                                width: 180
                                            })
                                                .addTextColumn({
                                                name: "nazev",
                                                caption: "Název subřady",
                                                width: 200
                                            })
                                            //.addTextColumn({
                                            //    name: "uus",
                                            //    caption: "ÚUS",
                                            //    width: 120
                                            //})
                                        }).show().then((result) => {
                                            if (!!result) {
                                                vstupy.zobrazovatDialogVyberSubradu = false;
                                                vstupy.subrada = result.subrada;
                                                vstupy.uus = result.uus;
                                                return VolejSchvaleni(vstupy, that, radkyKrylik, detailKontace, dataSentence); // Volam rekurzivne schvaleni se zmenenymi vstupy
                                            }
                                        });
                                    case "rozvrh":
                                        return that.dialogs.confirm("Doplnění do rozvrhu", ctx.baseMessage, 400, 400).createDialogPromise("yes").then(function () {
                                            let newValue = {};
                                            let allDW = dataSentence.allSortedDataWords;
                                            let i = 0;
                                            do {
                                                if (allDW[i].Pouziti === 0) {
                                                    newValue[allDW[i].DbNazev] = allDW[i].Prazdny;
                                                }
                                                else {
                                                    newValue[allDW[i].DbNazev] = data.radekRozvrhu[allDW[i].DbNazev] ?? allDW[i].Prazdny;
                                                    if (allDW[i].Poradi === data.poradi) {
                                                        newValue.uroven = allDW[i].UrovenNum;
                                                        newValue.urovenStr = allDW[i].Uroven || "";
                                                        break;
                                                    }
                                                }
                                            } while (++i < allDW.length);
                                            var mode = "addWithDS";
                                            if (data.moznostPorizeni === 1)
                                                mode = "editWithDS";
                                            return Gordic.Eko.WebClient.GNewRecordDlg.showDlg({
                                                mode: mode,
                                                wordSequence: data.poradi,
                                                newValue: newValue,
                                                dataSentence: dataSentence,
                                                row: { nazev: data.radekRozvrhu.nazev, poradi: data.poradi }
                                            })
                                                .then(() => { return VolejSchvaleni(vstupy, that, radkyKrylik, detailKontace, dataSentence); });
                                        });
                                }
                            }
                        }
                    })
                        .always(() => that.endOperation());
                }
                GKryLikTools.VolejSchvaleni = VolejSchvaleni;
