                ZmenaSubradyZKnihy(opts) {
                    var that = this;
                    var currentDataRow = this.$grid.ggrid("activeRow", true); // načtení přes vyhledání gridu (přes metadata)
                    if (currentDataRow != null) {
                        const currentOpts = $.extend({
                            ixp: this.batoh.ixp, currentDataRow: currentDataRow.data,
                            showDialog: true
                        }, opts);
                        return this.call("ZmenaSubradyZKnihy", currentOpts)
                            .then(() => {
                            this.view.requestData();
                            //Gordic.Eko.Dialogs.GVazby(this, { InputDto: { viewMode: true, ixp: that.batoh.ixp!, drd: 0, ktg_typ: that.batoh.ktg_typ!, lzePracovatSCizimiDoklady: false } });  // volání účetních zápisů
                        }, (err) => {
                            if (err instanceof GServerError) { // Pokud je chyba vyjimka, osetrim si ji tu    
                                const ctx = err.details;
                                if (ctx["exceptionType"] != "Gordic.General.GDataInvalidException") {
                                    this.endOperation(); // smaz informacni hlasku
                                    return this.dialogs.error(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                                }
                                else {
                                    const data = ctx.data;
                                    switch (data.exceptionType) {
                                        case "error":
                                            this.endOperation(); // smaz informacni hlasku
                                            return this.dialogs.error(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                                        case "info":
                                            this.endOperation(); // smaz informacni hlasku
                                            return this.dialogs.alert(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                                        case "question":
                                            return this.dialogs.confirm(ctx.baseMessage).createDialogPromise("yes")
                                                .then(function () {
                                                currentOpts.showDialog = false;
                                                return that.ZmenaSubradyZKnihy(currentOpts);
                                            });
                                    }
                                }
                            }
                        });
                    }
                }
                ZmenaSubrady(opts) {
                    var that = this;
                    var currentDataRow = this.$grid.ggrid("activeRow", true); // načtení přes vyhledání gridu (přes metadata)
                    if (currentDataRow != null) {
                        const currentOpts = $.extend({
                            ixp: this.batoh.ixp, currentDataRow: currentDataRow.data,
                            showVyberRadek: true, showDialog: true, subrada: -1, uus: ""
                        }, opts);
                        return this.call(currentOpts.metoda, currentOpts)
                            .then(() => {
                            this.view.requestData();
                            //Gordic.Eko.Dialogs.GVazby(this, { InputDto: { viewMode: true, ixp: that.batoh.ixp!, drd: 0, ktg_typ: that.batoh.ktg_typ!, lzePracovatSCizimiDoklady: false } });  // volání účetních zápisů
                        }, (err) => {
                            if (err instanceof GServerError) { // Pokud je chyba vyjimka, osetrim si ji tu    
                                const ctx = err.details;
                                if (ctx["exceptionType"] != "Gordic.General.GDataInvalidException") {
                                    this.endOperation(); // smaz informacni hlasku
                                    return this.dialogs.error(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                                }
                                else {
                                    const data = ctx.data;
                                    switch (data.exceptionType) {
                                        case "error":
                                            this.endOperation(); // smaz informacni hlasku
                                            return this.dialogs.error(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                                        case "info":
                                            this.endOperation(); // smaz informacni hlasku
                                            return this.dialogs.alert(ctx.baseMessage); // Zobraz dialog a ukonci cinnost
                                        case "question":
                                            return this.dialogs.confirm(ctx.baseMessage).createDialogPromise("yes")
                                                .then(() => {
                                                currentOpts.showDialog = false;
                                                return this.ZmenaSubrady(currentOpts);
                                            });
                                        case "vyber":
                                            //return this.call("GetSubradaDuzUcet").then((data) => {
                                            return new Gordic.Data.Selectors.DefaultSelector({
                                                related: that.element,
                                                title: "Výběr",
                                                canSelectEmpty: false,
                                                data: data.data,
                                                gridFormat: new Gordic.Data.GridFormat()
                                                    .addNumberColumn({
                                                    name: "subrada",
                                                    caption: "Subřada",
                                                    width: 180
                                                })
                                                    .addTextColumn({
                                                    name: "nazev",
                                                    caption: "Název subřady",
                                                    width: 200
                                                })
                                                //.addTextColumn({
                                                //    name: "uus",
                                                //    caption: "ÚUS",
                                                //    width: 120
                                                //})
                                            }).show().done((result) => {
                                                if (!!result) {
                                                    currentOpts.showVyberRadek = false;
                                                    currentOpts.subrada = result.subrada;
                                                    currentOpts.uus = result.uus;
                                                    return this.ZmenaSubrady(currentOpts);
                                                }
                                            });
                                        //})
                                    }
                                }
                            }
                        });
                    }
                }
                //*****************************************************
