                        //        this.setPending(that.saveCheck1(souhrnData).then(() => { return that.saveCheck2(souhrnData) }).then(() => {
                        //            return that.isl.BplFakturaDoslaVecnyProfil.ulozPopisy({ ixp: that.ixp, popisNad: that.$poznamkaNad.findFields("poznamkaNad").gfield("getValue"), popisPod: that.$poznamkaPod.findFields("poznamkaPod").gfield("getValue") })
                        //                .getData().done(() => {
                        //                    that.$grid.ggrid("getView").requestData();
                        //            })
