                //#region Tab Rekapitulace
                /** Vytvoření tabu Rekapitulace s souhrným gridem a formulářem */
                createRekapitulace() {
                    var tab = $.newDiv().appendTo(this.element).gtab({
                        id: "tabRekapitulace",
                        title: "jres:33600032", //RC 33600032 : Rekapitulace
                        opened: true
                    });
                    var formBuilder = new Gordic.Forms.Form({ layoutDescriptor: "L2M1S1" });
                    formBuilder.addSection({ layoutDescriptor: "L-0-12-0, M-0-12-0, S-0-12-0" })
                        .addField("ggrid", {
                        name: "gridRecap",
                        columns: this.createRecapColumns(),
                        columnMode: "full",
                        defaultProfile: {
                            grouping: "dan_proc",
                            sort: "dan_proc"
                        }
                    });
                    formBuilder.addSection()
                        .addRow("jres:33600033" + this.mena) //RC 33600033 : Součet položek v 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "soucetZaPolozky",
                        defaultValue: new Decimal(0.00),
                        disabled: true
                    }).addRow("jres:33600034" + this.mena) //RC 33600034 : Zaokrouhlení v 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "zaokrouhleni",
                        defaultValue: new Decimal(0.00),
                        disabled: true
                    }).addRow("jres:33600035" + this.mena) //RC 33600035 : Částka faktury v 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "castkaFaktury",
                        defaultValue: new Decimal(0.00),
                        disabled: !(this.AppStr == "kof" && this.l_oAutZaokr), //+ dokladovaPodminka
                        change: (ev, ctx) => {
                            if (ctx.value) { //TODO: otestovat po rozjetí KOF!
                                this.$formSouhrn.findFields("zaokrouhleni").gfield("setValue", parseDecimal(ctx.value).minus(this.$formSouhrn.findFields("soucetZaPolozky").gfield("getValue")));
                                this.castka = parseDecimal(ctx.value).toDecimalPlaces(2);
                            }
                            else {
                                this.$formSouhrn.findFields("zaokrouhleni").gfield("setValue", parseDecimal(0).minus(this.$formSouhrn.findFields("soucetZaPolozky").gfield("getValue")));
                            }
                        }
                    }).addRow("jres:33600036" + this.mena) //RC 33600036 : Částka záloh v 
                        .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                        name: "castkaZaloh",
                        defaultValue: new Decimal(0.00),
                        disabled: true
                    });
                    this.$formSouhrn = $.newDiv().appendTo(tab).gform("createFrom", formBuilder);
                    this.$gridRecap = tab.find("[data-help-context='list:gridRecap']");
                    this.$gridRecap.ggrideko({
                        summaryRowAllowed: true,
                        longListAllowed: false
                    });
                }
                /** Vytvoření gridformátu pro rekapitulaci částek sazby daně */
                createRecapColumns() {
                    var gridFormat = new Gordic.Data.GridFormat();
                    gridFormat.addTextColumn({
                        name: "dan_proc",
                        caption: "jres:33600037", //RC 33600037 : Sazba DPH %
                        width: 200,
                        groupings: {
                            "default": {
                                _presetCaption: "jres:33600038", //RC 33600038 : Dle hodnoty
                                grouping: {
                                    hideColumn: false
                                }
                            }
                        }
                    }).addCurrencyColumn({
                        name: "c_upravena" + this.suffix,
                        caption: "jres:33600039", //RC 33600039 : Základ
                        width: 100
                    }).addCurrencyColumn({
                        name: "c_dan" + this.suffix,
                        caption: "jres:33600040", //RC 33600040 : Daň
                        width: 100
                    });
                    if (this.dodaneni) {
                        gridFormat.addCurrencyColumn({
                            name: "c_dodan" + this.suffix,
                            caption: "jres:33600028", //RC 33600028 : Dodanění
                            width: 100
                        });
                    }
                    gridFormat.addCurrencyColumn({
                        name: "c_upravena_c_dan",
                        caption: "jres:33600044", //RC 33600044 : Základ + daň
                        width: 100
                    });
                    return gridFormat;
                }
                //#endregion
                /**
                 * Nastavení názvu, přístupnosti a příznaku tlačítka materiály
                 * @param data Seznam položek
                 */
                setSklady(data) {
                    if (this.pok_rad_pspovol == 100) {
                        var schvalene = 0;
                        var neschvalene = 0;
                        //projedu data, zda jsou tam schválené nebo neschválené položky
                        for (let row of data) {
                            if (row.mp_stav == 20) {
                                schvalene++;
                            }
                            else if (row.mp_stav == 10) {
                                neschvalene++;
                            }
                        }
                        var tag; //TODO: upravit na atribut třídy pro využití v permissions? a run()
                        var enabled = true;
                        var caption;
                        if (schvalene > 0 && neschvalene == 0) { //vše je schváleno --- 1
                            if (this.AppStr == "kdf") {
                                caption = "jres:33600041"; //RC 33600041 : Zrušení příjmu
                            }
                            else if (this.AppStr == "kof") {
                                caption = "jres:33600042"; //RC 33600042 : Zrušení výdeje
                            }
                            tag = 1;
                        }
                        else if ((schvalene == 0 && neschvalene > 0) || (schvalene == 0 && neschvalene == 0)) { //vše je neschváleno --- 0 nebo null
                            if (this.AppStr == "kdf") {
                                caption = "jres:33600043"; //RC 33600043 : Příjem na sklad
                            }
                            else if (this.AppStr == "kof") {
                                caption = "jres:33600007"; //RC 33600007 : Výdej ze skladu
                            }
                            tag = 0;
                        }
                        else if (schvalene > 0 && neschvalene > 0) { //divný stav - něco schváleno - něco neschváleno --- -1
                            enabled = false;
                            if (this.AppStr == "kdf") {
                                caption = "jres:33600043"; //RC 33600043 : Příjem na sklad
                            }
                            else if (this.AppStr == "kof") {
                                caption = "jres:33600007"; //RC 33600007 : Výdej ze skladu
                            }
                            tag = -1;
                        }
                        this.actions.actMaterialy?.update({ enabled: enabled, caption: caption });
                    }
                }
                /**
                 * Nastavení hodnot v tabu rekapitulace
                 * @param data Seznam položek
                 */
                setRekapitulace(data) {
                    if (!data) {
                        data = this.$grid.ggrid("getView").getDataRows();
                    }
                    var soucet = new Decimal(0.00);
                    for (let row of data) {
                        row["c_upravena_c_dan"] = parseDecimal(row["c_upravena" + this.suffix]).plus(parseDecimal(row["c_dan" + this.suffix]));
                        if (this.menaCzk == RezimMeny.CZK) {
                            soucet = soucet.plus(row.c_upravena_czk).plus(row.c_dan_czk);
                        }
                        else {
                            soucet = soucet.plus(row.c_mena).plus(row.c_upr).plus(row.c_dan);
                        }
                    }
                    this.$gridRecap.ggrid("setData", data);
                    var zaokrouhleni = new Decimal(0.00);
                    if (this.AppStr != "kof" || (this.AppStr == "kof" && this.prizSplatky)) {
                        zaokrouhleni = parseDecimal(this.castka).minus(soucet);
                    }
                    this.$formSouhrn.findFields().gfield("model", "apply", { soucetZaPolozky: soucet, zaokrouhleni: zaokrouhleni, castkaFaktury: this.castka, castkaZaloh: this.zaloha }, { initialValues: true });
                }
