                            let datumUHR = (data.dat_uhr != null) ? " - " + Gordic.Templates.Formatters.date(data.dat_uhr) : ""; // lokální datum '01.01.2022'
                            let stavKryti = data.cc_stavKryti; // pomocný stav krytí
